import numpy as np
from rcb_client import Robot
r=Robot();spec=r.spec();p=np.array(spec['arm']['position_m'],float);w=np.array(spec['arm']['axis'],float);ee0=np.array(spec['arm']['end_effector']['position_m'],float)
def skew(v):return np.array([[0,-v[2],v[1]],[v[2],0,-v[0]],[-v[1],v[0],0]])
def fk(q):
 T=np.eye(4);orig=[];axes=[]
 for ax,th,pt in zip(w,q,p):
  axes.append(T[:3,:3]@ax);orig.append(T[:3,:3]@pt+T[:3,3]);R=np.eye(3)+np.sin(th)*skew(ax)+(1-np.cos(th))*skew(ax)@skew(ax);G=np.eye(4);G[:3,:3]=R;G[:3,3]=pt-R@pt;T=T@G
 e=T[:3,:3]@ee0+T[:3,3];return T[:3,:3],e,np.array(orig),np.array(axes)
def rotlog(R):
 c=np.clip((np.trace(R)-1)/2,-1,1);t=np.arccos(c)
 if t<1e-8:return np.zeros(3)
 return t/(2*np.sin(t))*np.array([R[2,1]-R[1,2],R[0,2]-R[2,0],R[1,0]-R[0,1]])
o=r.observe(images=False);q=np.array(o['proprio']['arm_pos'],float);bx,by,yaw=o['proprio']['base_pose'];B=np.array([[np.cos(yaw),-np.sin(yaw),0],[np.sin(yaw),np.cos(yaw),0],[0,0,1]]);off=np.array([bx,by,0]);R,e,*_=fk(q);Rtar=B@R;xy=(B@e+off)[:2];print('start xyz',np.r_[xy,(B@e+off)[2]])
for z in [.201,.251,.301]:
 target=np.r_[xy,z];print('target',target)
 for it in range(12):
  R,e,orig,axes=fk(q);Rw=B@R;ew=B@e+off;ep=target-ew;er=rotlog(Rtar@Rw.T);err=np.r_[ep,.15*er]
  if np.linalg.norm(ep)<.002 and np.linalg.norm(er)<.01:break
  Jv=np.array([np.cross(axes[i],e-orig[i]) for i in range(7)]).T;J=np.vstack([B@Jv,.15*B@axes.T]);dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,err);dq=np.clip(dq,-.07,.07)
  row=np.r_[0,0,0,dq,0].tolist();res=r.step('delta',row,images=False);print('  ',res['step'],'blocked',res.get('blocked'),'err',np.round(ep,3),'dq',np.round(dq,3))
  if res.get('blocked'):raise SystemExit('BLOCKED')
  q=np.array(res['proprio']['arm_pos'],float)
print('final',r.observe(images=False)['proprio'])
